SELECT * FROM com_sales_order
WHERE tenant_id = #{query.tenantId}
  AND source_system = #{query.sourceSystem}
  AND source_record_key = #{query.sourceRecordKey}
  AND deleted = 0
FOR UPDATE

SELECT * FROM com_sales_order
WHERE tenant_id = #{query.tenantId}
  AND deleted = 0
  AND CAST(company_code AS BINARY) IN

      CAST(#{companyCode} AS BINARY)


  AND order_no LIKE CONCAT('%', #{query.orderNo}, '%')


  AND status = #{query.status}

ORDER BY order_no, id
LIMIT #{query.offset}, #{query.limit}
